/*
 * repl.h — Read-Eval-Print Loop for Epilog.
 *
 * The REPL owns a persistent Database and AtomTable across queries.
 * Each query gets a fresh VarRegistry and TermArena slice.
 *
 * Commands:
 *   ?- <goals>.          run a query; print each solution; prompt for more
 *   :- consult('file').  load a .pl file (also accepted as bare filename)
 *   halt.                exit
 *
 * JPL rules: no recursion, bounded buffers, no post-init malloc.
 */

#ifndef EPILOG_REPL_H
#define EPILOG_REPL_H

#include "atoms.h"
#include "terms.h"
#include "variables.h"
#include "database.h"

#define REPL_LINE_MAX  1024U   /* max chars per input line */

typedef struct {
    AtomTable   atoms;
    Database    db;
    TermArena   arena;
    VarRegistry vars;
} ReplState;

/*
 * repl_init — initialise all sub-systems. Returns 0 or -1.
 * Must be called before repl_run or repl_load_file.
 */
int repl_init(ReplState *s);

/*
 * repl_load_file — parse and assert all clauses from path.
 * Returns 0 on success, -1 on file/parse error.
 * Prints error messages to stderr.
 */
int repl_load_file(ReplState *s, const char *path);

/*
 * repl_run — enter the interactive loop; reads from stdin.
 * Returns when the user types "halt." or EOF.
 */
void repl_run(ReplState *s);

#endif /* EPILOG_REPL_H */

