static TermRef parse_term(Parser *p)
{
    const Token *t;
    AtomId       aid;
    VarId        vid;
    TermRef      ref = TERM_REF_INVALID;

    t = peek(p);

    /* integer */
    if (t->kind == TOK_INT) {
        advance(p);
        ref = term_make_int(p->arena, t->int_val);
    }

    /* variable */
    else if (t->kind == TOK_VAR) {
        advance(p);
        vid = VAR_ID_INVALID;
        {
            uint32_t k;
            for (k = 0U; k < p->vars->count; ++k) {
