/*
 * atoms.c — Atom table implementation for the Epilog inference engine.
 *
 * Strategy: open-addressed hash table with linear probing.
 * All storage is pre-allocated in AtomTable (no malloc after init).
 *
 * JPL rules observed:
 *   Rule 1  — no goto, no setjmp/longjmp, no recursion.
 *   Rule 2  — every loop has a fixed upper bound (ATOM_TABLE_CAPACITY).
 *   Rule 3  — no dynamic memory allocation after atom_table_init().
 *   Rule 4  — no function exceeds ~60 lines.
 *   Rule 5  — every parameter validated; every return value is meaningful.
 *   Rule 6  — preprocessor used only for include and simple constants.
 *   Rule 7  — pointer depth ≤ 1 in all operations.
 *   Rule 8  — compiled with -Wall -Wextra -Wpedantic.
 */

#include "../include/atoms.h"

#include <assert.h>   /* assert()   */
#include <string.h>   /* memset, strncpy, strlen, strncmp */
#include <stdint.h>

/* -------------------------------------------------------------------------
 * Internal helpers
 * ------------------------------------------------------------------------- */

/* fnv1a_32 — FNV-1a 32-bit hash over a NUL-terminated string. */
static uint32_t fnv1a_32(const char *s)
{
    uint32_t hash = 2166136261U; /* FNV offset basis */
    uint32_t i;

    assert(s != NULL);

    for (i = 0U; i < ATOM_MAX_LEN + 1U && s[i] != '\0'; ++i) {
        hash ^= (uint32_t)(unsigned char)s[i];
        hash *= 16777619U; /* FNV prime */
    }
    return hash;
}

/*
 * probe_slot — linear-probe search.
 * Returns the index of the matching slot or the first empty slot.
 * *found is set to 1 if the atom already exists, 0 otherwise.
 * Returns ATOM_TABLE_CAPACITY when the table is full with no match.
 */
static uint32_t probe_slot(const AtomTable *t, const char *spelling,
                            uint32_t hash, int *found)
{
    uint32_t idx  = hash % ATOM_TABLE_CAPACITY;
    uint32_t step = 0U;

    assert(t       != NULL);
    assert(spelling != NULL);
    assert(found   != NULL);

    *found = 0;

    for (step = 0U; step < ATOM_TABLE_CAPACITY; ++step) {
        const Atom *slot = &t->slots[idx];

        if (slot->id == ATOM_ID_INVALID) {
            return idx; /* empty — can insert here */
        }

        if (slot->hash == hash &&
            strncmp(slot->spelling, spelling, ATOM_MAX_LEN) == 0) {
            *found = 1;
            return idx; /* existing match */
        }

        idx = (idx + 1U) % ATOM_TABLE_CAPACITY;
    }

    return ATOM_TABLE_CAPACITY; /* table full, no match */
}

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

int atom_table_init(AtomTable *t)
{
    if (t == NULL) {
        return -1;
    }
    memset(t, 0, sizeof(AtomTable));
    return 0;
}

AtomId atom_intern(AtomTable *t, const char *spelling)
{
    uint32_t hash;
    uint32_t idx;
    int      found;
    size_t   len;
    Atom    *slot;

    if (t == NULL || spelling == NULL) {
        return ATOM_ID_INVALID;
    }

    len = strnlen(spelling, ATOM_MAX_LEN + 1U);
    if (len > ATOM_MAX_LEN) {
        return ATOM_ID_INVALID;
    }

    hash = fnv1a_32(spelling);
    idx  = probe_slot(t, spelling, hash, &found);

    if (idx == ATOM_TABLE_CAPACITY) {
        return ATOM_ID_INVALID; /* table full */
    }

    if (found) {
        return t->slots[idx].id;
    }

    /* Insert new atom. */
    assert(t->count < ATOM_TABLE_CAPACITY);

    slot = &t->slots[idx];
    /* memcpy + explicit NUL — avoids MSVC strncpy deprecation warning. */
    memcpy(slot->spelling, spelling, len);
    slot->spelling[len] = '\0';
    slot->hash = hash;
    slot->id   = (AtomId)(t->count + ATOM_ID_MIN);

    t->count++;
    return slot->id;
}

AtomId atom_lookup(const AtomTable *t, const char *spelling)
{
    uint32_t hash;
    uint32_t idx;
    int      found;
    size_t   len;

    if (t == NULL || spelling == NULL) {
        return ATOM_ID_INVALID;
    }

    len = strnlen(spelling, ATOM_MAX_LEN + 1U);
    if (len > ATOM_MAX_LEN) {
        return ATOM_ID_INVALID;
    }

    hash = fnv1a_32(spelling);
    idx  = probe_slot(t, spelling, hash, &found);

    if (!found || idx == ATOM_TABLE_CAPACITY) {
        return ATOM_ID_INVALID;
    }

    return t->slots[idx].id;
}

const char *atom_spelling(const AtomTable *t, AtomId id)
{
    uint32_t slot_index;
    uint32_t i;

    if (t == NULL || id == ATOM_ID_INVALID) {
        return NULL;
    }

    /*
     * Linear scan to find the slot whose id matches.
     * This path is not performance-critical (used for display / debug).
     * Bounded by ATOM_TABLE_CAPACITY (JPL Rule 2).
     */
    for (i = 0U; i < ATOM_TABLE_CAPACITY; ++i) {
        if (t->slots[i].id == id) {
            return t->slots[i].spelling;
        }
    }

    (void)slot_index; /* suppressed: unused after refactor */
    return NULL;
}

uint32_t atom_count(const AtomTable *t)
{
    if (t == NULL) {
        return 0U;
    }
    return t->count;
}

