    static TermArena   s_query_arena;
    static VarRegistry s_query_vars;

    AtomTable   &atoms;
    Database    &db;
    TermArena   &clause_arena;
    VarRegistry &clause_vars;
    TermArena   &query_arena;
    VarRegistry &query_vars;

    SolverCtx()
        : atoms(s_atoms), db(s_db),
          clause_arena(s_clause_arena), clause_vars(s_clause_vars),
          query_arena(s_query_arena), query_vars(s_query_vars)
    {
        atom_table_init(&atoms);
        db_init(&db);
        term_arena_init(&clause_arena);
        var_registry_init(&clause_vars);
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
    }

    /* Assert clauses from a source string. Returns number asserted or -1. */
    int load(const char *src)
    {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        int lex_r = lex(src, &toks);
        if (lex_r < 0) { fprintf(stderr,"[load] lex failed\n"); return -1; }
        var_registry_init(&clause_vars);
        Parser p;
        if (parser_init(&p, &toks, &clause_arena, &atoms, &clause_vars) < 0) {
            fprintf(stderr,"[load] parser_init failed\n"); return -1;
        }
        int n = 0;
        ParsedClause c;
        for (;;) {
            memset(&c, 0, sizeof(c));
            ParseResult r = parser_next_clause(&p, &c);
            if (r == PARSE_EOF) { break; }
            if (r != PARSE_OK)  {
                fprintf(stderr,"[load] parse error after %d clauses: code=%d msg=%s\n",n,(int)r,p.error_msg);
                return -1;
            }
            int ar = db_assert_last(&db, &c, &clause_arena);
            if (ar < 0) { fprintf(stderr,"[load] db_assert_last failed after %d clauses\n",n); return -1; }
